-- 011: Thai proxy library addition: elderly community eye screening and eyeglasses (GLOBAL entries: organization_id IS NULL, read-only in the app).
--
-- Additive and idempotent like 010: each row is inserted only if no global entry with the same name exists. Never deletes or edits rows.
-- Snapshot of the 3 entries added to database/proxies/th-2569.json (the source of truth; `php bin/load-proxies.php` updates changed entries).
-- Every entry carries its source, a link and its limitations. Re-check the rates against their sources before reports.

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่าตรวจวัดสายตาและประกอบแว่นสายตายาว (เลนส์ชั้นเดียว) ผู้สูงอายุ ตามอัตรา สปสช.', 'ราคาต่อ 1 อันของบริการตรวจวัดสายตาพร้อมประกอบแว่นสายตาและเลนส์ชั้นเดียว สำหรับผู้สูงอายุที่มีปัญหาสายตายาวหรือกันแสง ตามราคาที่ สปสช. กำหนดและท้องถิ่นใช้จัดซื้อจัดจ้างผ่านกองทุนหลักประกันสุขภาพระดับท้องถิ่น (กปท.) ใช้เป็นมูลค่าทดแทนของการได้แว่นที่ตรงกับค่าสายตา', 'Health and wellbeing', 'บาท / อัน', 'THB', 200, 'ประเทศไทย (อัตรา สปสช. ที่ท้องถิ่นนำมาใช้)', 2025, 'ประกาศผู้ชนะการเสนอราคา จ้างบริการตรวจวัดสายตา พร้อมประกอบแว่นสายตา สำหรับผู้สูงอายุ องค์การบริหารส่วนตำบลแพรกหนามแดง (15 พ.ค. 2568) ซึ่งระบุว่าเป็นราคาและหลักเกณฑ์ตามที่ สำนักงานหลักประกันสุขภาพแห่งชาติ (สปสช.) กำหนด', 'http://www.phragnamdang.go.th/site/index.php?view=article&catid=75:2016-04-13-09-58-21&id=3351:15--68-----------x------&format=pdf', 'อ่านจากประกาศจัดจ้างของ อปท. แห่งหนึ่งที่ระบุว่าเป็นอัตราของ สปสช. ไม่ใช่ประกาศ สปสช. ฉบับจริง (เว็บไซต์ สปสช. ไม่เปิดให้อ่านอัตโนมัติ) ควรตรวจกับ สปสช. หรือสำนักงานกองทุนในพื้นที่ ราคา 200 บาทสำหรับสายตายาวพบตรงกันในโครงการ กปท. อื่นปี 2563 ด้วย เป็นราคาแว่นพื้นฐานเลนส์ชั้นเดียวซึ่งต่ำกว่าราคาร้านทั่วไปมาก จึงเป็นค่าต่ำแบบอนุรักษ์นิยม ไม่ครอบคลุมกรอบพิเศษ เลนส์หลายชั้น หรือการรักษาโรคตา ประกาศไม่ได้ระบุว่ารวมการตรวจโดยจักษุแพทย์หรือไม่ ถ้าโครงการซื้อแว่นราคาอื่นให้ใช้ต้นทุนจริง ถ้าใช้เป็นมูลค่าผลลัพธ์ ต้องหักส่วนที่ผู้สูงอายุจะซื้อแว่นเองอยู่แล้ว (deadweight) และอย่านับค่านี้ซ้ำทั้งเป็นต้นทุนและผลลัพธ์'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่าตรวจวัดสายตาและประกอบแว่นสายตายาว (เลนส์ชั้นเดียว) ผู้สูงอายุ ตามอัตรา สปสช.');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่าตรวจวัดสายตาและประกอบแว่นสายตาสั้น/ผสม/เอียง (เลนส์ชั้นเดียว) ผู้สูงอายุ ตามอัตรา สปสช.', 'ราคาต่อ 1 อันของบริการตรวจวัดสายตาพร้อมประกอบแว่นสายตาและเลนส์ชั้นเดียว สำหรับผู้สูงอายุที่มีปัญหาสายตาผสม (สั้นและยาว) หรือสายตาเอียง ตามราคาที่ สปสช. กำหนดและท้องถิ่นใช้จัดซื้อจัดจ้างผ่านกองทุนหลักประกันสุขภาพระดับท้องถิ่น (กปท.)', 'Health and wellbeing', 'บาท / อัน', 'THB', 500, 'ประเทศไทย (อัตรา สปสช. ที่ท้องถิ่นนำมาใช้)', 2025, 'ประกาศผู้ชนะการเสนอราคา จ้างบริการตรวจวัดสายตา พร้อมประกอบแว่นสายตา สำหรับผู้สูงอายุ องค์การบริหารส่วนตำบลแพรกหนามแดง (15 พ.ค. 2568) ซึ่งระบุว่าเป็นราคาและหลักเกณฑ์ตามที่ สำนักงานหลักประกันสุขภาพแห่งชาติ (สปสช.) กำหนด', 'http://www.phragnamdang.go.th/site/index.php?view=article&catid=75:2016-04-13-09-58-21&id=3351:15--68-----------x------&format=pdf', 'อ่านจากประกาศจัดจ้างของ อปท. แห่งหนึ่งที่ระบุว่าเป็นอัตราของ สปสช. ไม่ใช่ประกาศ สปสช. ฉบับจริง ควรตรวจกับ สปสช. หรือสำนักงานกองทุนในพื้นที่ ราคา 500 บาทสำหรับสายตาสั้นหรือเอียงพบตรงกันในโครงการ กปท. ปี 2563 และในโครงการของเทศบาลนครรังสิตปีงบประมาณ 2567 (500 บาท/คน) เป็นราคาแว่นพื้นฐานเลนส์ชั้นเดียวซึ่งต่ำกว่าราคาร้านทั่วไปมาก จึงเป็นค่าต่ำแบบอนุรักษ์นิยม ไม่ครอบคลุมกรอบพิเศษ เลนส์หลายชั้น หรือการรักษาโรคตา ถ้าโครงการซื้อแว่นราคาอื่นให้ใช้ต้นทุนจริง ถ้าใช้เป็นมูลค่าผลลัพธ์ ต้องหักส่วนที่ผู้สูงอายุจะซื้อแว่นเองอยู่แล้ว (deadweight) และอย่านับค่านี้ซ้ำทั้งเป็นต้นทุนและผลลัพธ์'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่าตรวจวัดสายตาและประกอบแว่นสายตาสั้น/ผสม/เอียง (เลนส์ชั้นเดียว) ผู้สูงอายุ ตามอัตรา สปสช.');

INSERT INTO financial_proxies (organization_id, name, definition, category, unit, currency, value, geography, reference_year, source, source_url, limitations)
SELECT NULL, 'ค่ารักษาผู้สูงอายุกระดูกสะโพกหัก เฉลี่ยต่อราย (โรงพยาบาลกาฬสินธุ์ ปี 2565)', 'งบประมาณรักษาเฉลี่ยต่อรายของผู้สูงอายุที่กระดูกสะโพกหัก ซึ่งส่วนใหญ่เกิดจากการพลัดตกหกล้ม ใช้เป็นฐานต่ำของต้นทุนการรักษาที่หลีกเลี่ยงได้ เมื่อโครงการมีหลักฐานว่าการแก้ไขสายตาช่วยลดการหกล้มของผู้สูงอายุกลุ่มเป้าหมาย', 'Health and wellbeing', 'บาท / ราย', 'THB', 74000, 'โรงพยาบาลกาฬสินธุ์ จังหวัดกาฬสินธุ์', 2022, 'จันทร์เพ็ญ ภูตะวัน. การพยาบาลผู้ป่วยสูงอายุกระดูกข้อสะโพกหักร่วมกับภาวะแทรกซ้อน โรงพยาบาลกาฬสินธุ์: กรณีศึกษา. วารสารอนามัยสิ่งแวดล้อมและสุขภาพชุมชน 2566;8(3):198-208 (อ้างสถิติของโรงพยาบาลกาฬสินธุ์ ปี 2565)', 'https://he03.tci-thaijo.org/index.php/ech/article/download/1889/1314/12412', 'เป็นตัวเลขของโรงพยาบาลแห่งเดียว ที่บทความอ้างจากสถิติภายในโรงพยาบาล ไม่ใช่งานวิจัยต้นทุนโดยตรง และไม่อธิบายว่ารวมรายการใดบ้าง ไม่รวมการฟื้นฟูระยะยาว ภาระผู้ดูแล และการสูญเสียความสามารถ ที่สำคัญ แหล่งนี้ไม่ได้แสดงว่าแว่นสายตาลดการหกล้มได้ การนำไปใช้ต้องมีหลักฐานว่าโครงการทำให้ผู้สูงอายุกี่รายหลีกเลี่ยงการหกล้มจนสะโพกหัก (attribution) ถ้าไม่มีหลักฐานนี้ไม่ควรนับเป็นผลลัพธ์หลัก ให้ใช้เป็นการวิเคราะห์ความอ่อนไหวด้วยสมมติฐานอนุรักษ์นิยม และหักส่วนที่เกิดขึ้นเองอยู่แล้ว (deadweight) ควรปรับเงินเฟ้อจากปี 2565'
WHERE NOT EXISTS (SELECT 1 FROM financial_proxies WHERE organization_id IS NULL AND name = 'ค่ารักษาผู้สูงอายุกระดูกสะโพกหัก เฉลี่ยต่อราย (โรงพยาบาลกาฬสินธุ์ ปี 2565)');
